20	using hybrid::test::DmiOp;
21	using hybrid::test::kDmstatusHaltedAndAcked;
22	using hybrid::test::RecordingBus;
23	using RD = hybrid::ResumeDriver;
24	
25	// L26: the V scratch GPA is a runtime value (mmap top page) passed to the
26	// drain. The V dump-sweep tests pass this distinctive stand-in.
27	static constexpr uint64_t kScratch = 0x07FFF000ull;  // 128 MiB mmap top page
28	
29	TEST_CASE("state_drain primes dmactive then issues haltreq before any read")
30	{
31	  RecordingBus bus;
32	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
33	
34	  hybrid::StateDrain drain(bus, kScratch);
35	  (void) drain.drain();
36	
37	  REQUIRE(bus.ops.size() >= 2);
38	  CHECK(bus.ops[0].kind == DmiOp::Kind::Write);
39	  CHECK(bus.ops[0].reg == RD::kDmcontrol);
40	  CHECK((bus.ops[0].value & RD::kDmcontrolDmactive) != 0u);
41	  CHECK((bus.ops[0].value & RD::kDmcontrolHaltreq) == 0u);
42	
43	  CHECK(bus.ops[1].kind == DmiOp::Kind::Write);
44	  CHECK(bus.ops[1].reg == RD::kDmcontrol);
45	  CHECK((bus.ops[1].value & RD::kDmcontrolDmactive) != 0u);
46	  CHECK((bus.ops[1].value & RD::kDmcontrolHaltreq) != 0u);
47	}
48	
49	TEST_CASE("state_drain reads x1..x31 via Abstract Commands, skipping x0")
50	{
51	  RecordingBus bus;
52	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
53	  for (uint16_t i = 0; i < 32; ++i)
54	    bus.regfile[hybrid::regno_gpr(i)] = 0xa00000000ULL + i;
55	
56	  hybrid::StateDrain drain(bus, kScratch);
57	  const auto state = drain.drain();
58	
59	  for (int i = 1; i < 32; ++i) {
60	    CHECK(state.gpr[i] == 0xa00000000ULL + i);
61	  }
62	  for (const auto& op : bus.ops) {
63	    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand) {
64	      const uint16_t regno = op.value & 0xffffu;
65	      CHECK(regno != hybrid::regno_gpr(0));
66	    }
67	  }
68	}
69	
70	TEST_CASE("state_drain captures pc from DPC")
71	{
72	  RecordingBus bus;
73	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
74	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x12345678'9ABCDEF0ULL;
75	
76	  hybrid::StateDrain drain(bus, kScratch);
77	  const auto state = drain.drain();
78	
79	  CHECK(state.pc == 0x12345678'9ABCDEF0ULL);
80	}
