82	TEST_CASE("state_drain populates header fields (magic, version, flags)")
83	{
84	  RecordingBus bus;
85	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
86	
87	  hybrid::StateDrain drain(bus, kScratch);
88	  const auto state = drain.drain();
89	
90	  CHECK(state.magic == HYBRID_STATE_MAGIC);
91	  CHECK(state.version == HYBRID_STATE_VERSION);
92	  CHECK((state.flags & HYBRID_FLAG_RV64) != 0u);
93	}
