95	TEST_CASE("state_drain issues a COMMAND read for each x1..x31 + DPC")
96	{
97	  RecordingBus bus;
98	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
99	
100	  hybrid::StateDrain drain(bus, kScratch);
101	  (void) drain.drain();
102	
103	  std::size_t cmd_count = 0;
104	  for (const auto& op : bus.ops)
105	    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand) ++cmd_count;
106	  CHECK(cmd_count >= 32u);
107	}
