109	TEST_CASE("drain() does NOT issue Abstract Commands for FPRs/CSRs/PMPs - those "
110	          "fields are zero in the bare drain output and merged in by "
111	          "drain_with_passthrough")
112	{
113	  RecordingBus bus;
114	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
115	  for (uint16_t i = 0; i < 32; ++i)
116	    bus.regfile[hybrid::regno_fpr(i)] = 0xf000000000000000ULL + i;
117	
118	  hybrid::StateDrain drain(bus, kScratch);
119	  const auto state = drain.drain();
120	
121	  for (int i = 0; i < 32; ++i) CHECK(state.fpr[i] == 0u);
122	  CHECK(state.mstatus == 0u);
123	  CHECK(state.satp    == 0u);
124	  CHECK(state.vlenb   == 0u);
125	}
126	
127	TEST_CASE("drain_with_passthrough copies CSR/PMP/V-payload slots from input and "
128	          "freshly drains GPRs/PC from the DM")
129	{
130	  RecordingBus bus;
131	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
132	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80001234ULL;
133	  for (uint16_t i = 0; i < 32; ++i)
134	    bus.regfile[hybrid::regno_gpr(i)] = 0x10000000ULL + i;
135	
136	  hybrid_state_v1 input{};
137	  input.magic   = HYBRID_STATE_MAGIC;
138	  input.version = HYBRID_STATE_VERSION;
139	  input.flags   = HYBRID_FLAG_RV64;
140	  input.priv    = 3;
141	  input.mstatus = 0x1800ULL;
142	  input.satp    = 0x8000000080000000ULL;
143	  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  input.pmpcfg[i]  = 0xa0 + i;
144	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) input.pmpaddr[i] = 0xb0 + i;
145	  input.vlenb = 64;
146	  for (std::size_t i = 0; i < sizeof(input.vreg); ++i) input.vreg[i] = i & 0xff;
147	
148	  hybrid::StateDrain drain(bus, kScratch);
149	  const auto state = drain.drain_with_passthrough(input);
150	
151	  CHECK(state.mstatus == 0x1800ULL);
152	  CHECK(state.satp    == 0x8000000080000000ULL);
153	  CHECK(state.pmpcfg[5]  == uint64_t(0xa5));
154	  CHECK(state.pmpaddr[7] == uint64_t(0xb7));
155	  CHECK(state.vlenb == 64ULL);
156	  CHECK(state.vreg[100] == uint8_t(100));
157	
158	  // GPRs/PC come from the DM read, not the input.
159	  for (int i = 1; i < 32; ++i)
160	    CHECK(state.gpr[i] == 0x10000000ULL + uint64_t(i));
161	  CHECK(state.pc == 0x80001234ULL);
162	}
