164	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_FP: FPRs read from DM, not input")
165	{
166	  RecordingBus bus;
167	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
168	  for (uint16_t i = 0; i < 32; ++i)
169	    bus.regfile[hybrid::regno_fpr(i)] = 0xf000000000000000ULL + i;
170	
171	  hybrid_state_v1 input{};
172	  input.magic   = HYBRID_STATE_MAGIC;
173	  input.version = HYBRID_STATE_VERSION;
174	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
175	  input.priv    = 3;
176	  // Stale QEMU1 values that must be overwritten by the DM reads.
177	  for (int i = 0; i < 32; ++i) input.fpr[i] = 0xdeadbeef00000000ULL + i;
178	
179	  hybrid::StateDrain drain(bus, kScratch);
180	  const auto state = drain.drain_with_passthrough(input);
181	
182	  for (int i = 0; i < 32; ++i)
183	    CHECK(state.fpr[i] == 0xf000000000000000ULL + uint64_t(i));
184	}
