186	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_FP: FP reads issued after GPR reads")
187	{
188	  RecordingBus bus;
189	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
190	
191	  hybrid_state_v1 input{};
192	  input.magic   = HYBRID_STATE_MAGIC;
193	  input.version = HYBRID_STATE_VERSION;
194	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
195	  input.priv    = 3;
196	
197	  hybrid::StateDrain drain(bus, kScratch);
198	  (void) drain.drain_with_passthrough(input);
199	
200	  std::optional<std::size_t> last_gpr_cmd;
201	  std::optional<std::size_t> first_fpr_cmd;
202	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
203	    const auto& op = bus.ops[i];
204	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
205	    const uint16_t regno = op.value & 0xFFFFu;
206	    if (regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
207	      last_gpr_cmd = i;
208	    if (!first_fpr_cmd
209	        && regno >= hybrid::regno_fpr(0) && regno <= hybrid::regno_fpr(31))
210	      first_fpr_cmd = i;
211	  }
212	  REQUIRE(last_gpr_cmd.has_value());
213	  REQUIRE(first_fpr_cmd.has_value());
214	  CHECK(*last_gpr_cmd < *first_fpr_cmd);
215	}
