382	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: V CSR reads issued after GPR reads")
383	{
384	  RecordingBus bus;
385	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
386	
387	  hybrid_state_v1 input{};
388	  input.magic   = HYBRID_STATE_MAGIC;
389	  input.version = HYBRID_STATE_VERSION;
390	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
391	  input.priv    = 3;
392	
393	  hybrid::StateDrain drain(bus, kScratch);
394	  (void) drain.drain_with_passthrough(input);
395	
396	  // Find the last GPR COMMAND read and the first V CSR COMMAND read.
397	  std::optional<std::size_t> last_gpr_cmd;
398	  std::optional<std::size_t> first_vcsr_cmd;
399	  const std::initializer_list<uint16_t> vcsr_regnos = {
400	    hybrid::regno_csr(RD::kCsrVstart),
401	    hybrid::regno_csr(RD::kCsrVxsat),
402	    hybrid::regno_csr(RD::kCsrVxrm),
403	    hybrid::regno_csr(RD::kCsrVcsr),
404	    hybrid::regno_csr(RD::kCsrVtype),
405	    hybrid::regno_csr(RD::kCsrVl),
406	  };
407	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
408	    const auto& op = bus.ops[i];
409	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
410	    const uint16_t regno = op.value & 0xFFFFu;
411	    // Only register READS matter here. The V-data dump sweep also issues GPR
412	    // WRITES (x5/x6/x7 scratch) at the end of drain; those are not the
413	    // architectural GPR reads this ordering check is about.
414	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
415	    if (is_read && regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
416	      last_gpr_cmd = i;
417	    for (uint16_t vcsr : vcsr_regnos)
418	      if (is_read && !first_vcsr_cmd && regno == vcsr)
419	        first_vcsr_cmd = i;
420	  }
421	  REQUIRE(last_gpr_cmd.has_value());
422	  REQUIRE(first_vcsr_cmd.has_value());
423	  CHECK(*last_gpr_cmd < *first_vcsr_cmd);
424	}
