456	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0..v31 to scratch "
457	          "after the architectural counter/CSR reads")
458	{
459	  RecordingBus bus;
460	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
461	
462	  hybrid_state_v1 input{};
463	  input.magic   = HYBRID_STATE_MAGIC;
464	  input.version = HYBRID_STATE_VERSION;
465	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
466	  input.priv    = 3;
467	  input.vlenb   = 64;
468	
469	  hybrid::StateDrain drain(bus, kScratch);
470	  (void) drain.drain_with_passthrough(input);
471	
472	  // (a) all 32 registers are dumped as 4 LMUL=8 groups: one vse8.v per group
473	  //     base (v0/v8/v16/v24) covers 8 registers, landing in any progbuf slot of
474	  //     the single grouped Program-Buffer execution.
475	  std::vector<int> missing;
476	  std::optional<std::size_t> first_vse_idx;
477	  for (uint16_t g = 0; g < 32; g += 8) {
478	    const uint32_t want = hybrid::encode_vse8_v(static_cast<uint8_t>(g), 7);
479	    std::optional<std::size_t> at;
480	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
481	      const auto& op = bus.ops[i];
482	      if (op.kind == DmiOp::Kind::Write
483	          && op.reg >= hybrid::kProgbuf0
484	          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
485	          && op.value == want) { at = i; break; }
486	    }
487	    if (!at) { missing.push_back(g); continue; }
488	    if (!first_vse_idx || *at < *first_vse_idx) first_vse_idx = at;
489	  }
490	  CHECK(missing.empty());
491	  REQUIRE(first_vse_idx.has_value());
492	
493	  // (b) the dump sweep runs AFTER the mcycle/minstret reads, so the sweep's
494	  //     vse8.v insns (and any counter increments) cannot corrupt the drained
495	  //     counters. minstret(0xB02) is the last counter read before the sweep.
496	  std::optional<std::size_t> minstret_read_idx;
497	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
498	    const auto& op = bus.ops[i];
499	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
500	    const auto regno   = static_cast<uint16_t>(op.value & 0xFFFFu);
501	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
502	    if (is_read && regno == hybrid::regno_csr(0xB02)) minstret_read_idx = i;
503	  }
504	  REQUIRE(minstret_read_idx.has_value());
505	  CHECK(*minstret_read_idx < *first_vse_idx);
506	}
