  virtual void write(uint8_t reg, uint32_t value) = 0;
  virtual auto read(uint8_t reg) -> uint32_t = 0;
};

inline auto read_register_64(DmiBus& bus, uint16_t regno,
                             const char* poll_label) -> uint64_t;

class ResumeDriver
{
public:
  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
  // dmcontrol/dmstatus are run-control registers specific to this driver.
  static constexpr uint8_t kData0      = kDmiData0;
  static constexpr uint8_t kData1      = kDmiData1;
  static constexpr uint8_t kDmcontrol  = 0x10;
  static constexpr uint8_t kDmstatus   = 0x11;
  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
  static constexpr uint8_t kCommand    = kDmiCommand;

  static constexpr uint16_t kCsrDpc      = 0x7B1;
  static constexpr uint16_t kCsrDcsr     = 0x7B0;
  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;

    // drained state.mstatus may legitimately carry FS at Off (e.g. an OS
    // context-switched the regs away before the trigger fired) -- gating the
    // write on the drained field skips the enable and silently NACKs every
    // subsequent FPR write. Always write mstatus when FP is in scope;
    // force-OR Initial when the drained field is Off. This enable is local
    // to the vsim phase; the state.mstatus written to the handoff file is
    // left unmodified.
    if (state.flags & HYBRID_FLAG_FP) {
      uint64_t enable_mstatus = state.mstatus;
      if ((enable_mstatus & kMstatusFsMask) == 0)
        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
    }

    // FPR restore (requires mstatus.FS enabled above): one abstract register
    // write per f-reg. Abstract-only by design, like every non-V register
    // block -- the Program Buffer is reserved for state the abstract command
    // space cannot reach.
    if (state.flags & HYBRID_FLAG_FP) {
      for (uint16_t i = 0; i < 32; ++i)
        write_64bit_register(regno_fpr(i), state.fpr[i]);
      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
      // fallback scratch x5 is overwritten by the GPR loop below.
      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
    }

    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
    // in the drained privilege; M-mode states skip the write (prv already 3).
    // Before the GPR loop: a PB fallback would clobber scratch x5.
    if (state.priv != 3) {
      // L2 slice: with PMP implemented and no matching entry, every S/U
      // access faults (priv spec v1.10) -- mirror the producer's PMP block
      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
      // RV64. Tolerant writes: entries beyond what the hart implements
      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);

      const uint64_t dcsr =
        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
      write_csr_abstract_or_pb(kCsrDcsr,
                               (dcsr & ~uint64_t{0x3}) | state.priv);
      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
      // silently measure the ROI in the wrong privilege. Verify and abort.
      const uint64_t got =
        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
        & 0x3u;
      if (got != state.priv)
        throw std::runtime_error(
          "ResumeDriver::resume: engine does not implement privilege level "
          + std::to_string(state.priv)
          + " (dcsr.prv pinned to " + std::to_string(got)
          + "); pick an S/U-capable engine");
    }

    // GPRs + DPC (after every CSR write whose PB fallback uses x5 as
    // scratch, so x5 is safe to overwrite): one abstract register write per
    // GPR.
    for (uint16_t i = 1; i < 32; ++i)
      write_64bit_register(regno_gpr(i), state.gpr[i]);
    write_64bit_register(regno_csr(kCsrDpc), state.pc);

    write_csr_tolerant(kCsrMtvec, state.mtvec);

    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
    // register with no hardware side effects, legal to use inside a trap-free
    // ROI. Restore it so a value stashed before the handoff survives into the
    // vsim phase.
    write_csr_tolerant(kCsrMscratch, state.mscratch);

    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
    // interrupt-free ROI envelope these are ordinary read/write registers, so a
    // value stashed before the handoff must survive into the vsim phase (same
    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
    // hardware-driven pending bits, or mtval on a core that hardwires it)
    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
    // S-mode CSRs the M-only default engine does not implement (L3/L4).
    write_csr_tolerant(kCsrMepc,   state.mepc);
    write_csr_tolerant(kCsrMcause, state.mcause);
    write_csr_tolerant(kCsrMtval,  state.mtval);
    write_csr_tolerant(kCsrMie,    state.mie);
    write_csr_tolerant(kCsrMip,    state.mip);

    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
    // caches) but has no cache model, so without this the cycle engine resumes
    // at the ROI with caches at their reset default -- DISABLED -- and the
    // whole measured window runs uncached, inflating it severalfold. Tolerant
    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
    // write as a no-op, and a drained 0 (caches were off) restores the reset
    // state, so this is always safe to issue.
    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);

    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
    // from QEMU1's drain value. Without this, vsim's local counter starts
    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
    // overwrite here as the GPR loop already ran.
    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);

    clear_cmderr_if_set();
    request_resume();
    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
                   "ResumeDriver resume");
  }

private:
  void request_halt()
  {
    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
  }

  void request_resume()
  {
    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
  }

  void write_64bit_register(uint16_t regno, uint64_t value)
  {
    write_register_abstract(bus_, regno, value);
  }

  // Abstract-first CSR write with Program Buffer fallback.
  // Tries an abstract register write; if the DM signals cmderr, clears it,
  // stages the value in scratch_gpr via abstract GPR write, then executes a
  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
  // to x5 (t0) which the GPR restore loop overwrites later.
  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
                                 uint8_t scratch_gpr = 5)
  {

23:#define HYBRID_STATE_MAGIC   0x42594841u  // 'AHYB' little-endian
24:// Version 2 (L11): vreg[] widened from 64 to 128 bytes per register, which
27:#define HYBRID_STATE_VERSION 2u
29:#define HYBRID_FLAG_RV64 (1u << 0)
30:#define HYBRID_FLAG_FP   (1u << 1)
31:#define HYBRID_FLAG_V    (1u << 2)
35:// span per vector register; the LIVE width is the runtime `vlenb` field
37:// never disagree on offsets. A producer whose vlenb exceeds this ceiling
48:// 64 PMP entries; pmpcfg slots reserved at 16 so the layout works for both
50:#define HYBRID_PMP_CFG_NUM  16
51:#define HYBRID_PMP_ADDR_NUM 64
62:  uint64_t priv;  // 0=U, 1=S, 3=M
67:  uint64_t mstatus;
68:  uint64_t mepc;
70:  uint64_t mcause;
71:  uint64_t mtval;
72:  uint64_t mscratch;
75:  uint64_t mip;
76:  uint64_t mie;
79:  uint64_t satp;
81:  uint64_t pmpcfg[HYBRID_PMP_CFG_NUM];
82:  uint64_t pmpaddr[HYBRID_PMP_ADDR_NUM];
87:  uint64_t vlenb;
88:  uint8_t  vreg[32 * HYBRID_VLEN_BYTES_MAX];
94:  // HYBRID_FLAG_FP is set. Drained by the plugin, restored by ResumeDriver,
98:  uint64_t fcsr;
110:  uint8_t  reserved[208];  // zero-initialise on write; 256 - 3*8 (vxsat/vxrm/vcsr) - 8 (fcsr) - 2*8 (mcache_ctl/mmisc_ctl)

input.content:
// StateDrain halts the hart via the Debug Module and populates a
// hybrid_state_v1 with the architectural register file. Reuses
// ResumeDriver's DM register constants and DmiBus interface.

#pragma once

#include "hybrid/abstract_command.hpp"
#include "hybrid/dmi_poll.hpp"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"

#include <cstdint>

namespace hybrid
{

class StateDrain
{
public:
  using RD = ResumeDriver;

  explicit StateDrain(DmiBus& bus) : bus_{bus} {}

  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
  // drain_with_passthrough when the QEMU 1 snapshot is available.
  auto drain() -> hybrid_state_v1
  {
    hybrid_state_v1 state{};
    state.magic   = HYBRID_STATE_MAGIC;
    state.version = HYBRID_STATE_VERSION;
    state.flags   = HYBRID_FLAG_RV64;
    halt_and_capture_pc_priv(state);

    for (uint16_t i = 1; i < 32; ++i)
      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");

    return state;
  }

  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
  // (L20) so post-vsim FP modifications are captured (otherwise the stale
  // QEMU 1 snapshot leaks into the drained state).
  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
  // contribution would otherwise be discarded as the passthrough preserves
  // QEMU1's pre-handoff value.
  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
  {
    auto state = input;
    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt

    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
    // like the resume side -- the Program Buffer is reserved for state the
    // abstract command space cannot reach.
    for (uint16_t i = 1; i < 32; ++i)
      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");

    if (input.flags & HYBRID_FLAG_FP) {
      for (uint16_t i = 0; i < 32; ++i)
        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
    }

    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
    // dropped and the stale QEMU1 value passes through into the drained state.
    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));

    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
    // restores them), so re-read them -- an in-ROI write must reach the drained
    // state instead of the stale QEMU1 passthrough value.
    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));

    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));

    return state;
  }

private:
  // Halt the hart and capture the two control fields every drain path needs:
  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
  // blocks are filled by the caller, so drain() and drain_with_passthrough
  // share one halt + prologue. dmactive must transition 0->1 in its own write
  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
  void halt_and_capture_pc_priv(hybrid_state_v1& state)
  {
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
                   "StateDrain halt");

    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
                                  "StateDrain DCSR") & 0x3u;
    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
  }

  DmiBus& bus_;
};

}  // namespace hybrid

// StateDrain is the dual of ResumeDriver: halt the hart via the Debug Module,
// read x1..x31 + DPC via Abstract Commands, populate hybrid_state_v1.

#include "hybrid/abstract_command.hpp"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"
#include "hybrid/state_drain.hpp"
#include "recording_bus.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <optional>

#include <cstdint>

using hybrid::test::DmiOp;
using hybrid::test::kDmstatusHaltedAndAcked;
using hybrid::test::RecordingBus;
using RD = hybrid::ResumeDriver;

TEST_CASE("state_drain primes dmactive then issues haltreq before any read")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::StateDrain drain(bus);
  (void) drain.drain();

  REQUIRE(bus.ops.size() >= 2);
  CHECK(bus.ops[0].kind == DmiOp::Kind::Write);
  CHECK(bus.ops[0].reg == RD::kDmcontrol);
  CHECK((bus.ops[0].value & RD::kDmcontrolDmactive) != 0u);
  CHECK((bus.ops[0].value & RD::kDmcontrolHaltreq) == 0u);

  CHECK(bus.ops[1].kind == DmiOp::Kind::Write);
  CHECK(bus.ops[1].reg == RD::kDmcontrol);
  CHECK((bus.ops[1].value & RD::kDmcontrolDmactive) != 0u);
  CHECK((bus.ops[1].value & RD::kDmcontrolHaltreq) != 0u);
}

TEST_CASE("state_drain reads x1..x31 via Abstract Commands, skipping x0")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_gpr(i)] = 0xa00000000ULL + i;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain();

  for (int i = 1; i < 32; ++i) {
    CHECK(state.gpr[i] == 0xa00000000ULL + i);
  }
  for (const auto& op : bus.ops) {
    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand) {
      const uint16_t regno = op.value & 0xffffu;
      CHECK(regno != hybrid::regno_gpr(0));
    }
  }
}

TEST_CASE("state_drain captures pc from DPC")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x12345678'9ABCDEF0ULL;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain();

  CHECK(state.pc == 0x12345678'9ABCDEF0ULL);
}

TEST_CASE("state_drain populates header fields (magic, version, flags)")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain();

  CHECK(state.magic == HYBRID_STATE_MAGIC);
  CHECK(state.version == HYBRID_STATE_VERSION);
  CHECK((state.flags & HYBRID_FLAG_RV64) != 0u);
}

TEST_CASE("state_drain issues a COMMAND read for each x1..x31 + DPC")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::StateDrain drain(bus);
  (void) drain.drain();

  std::size_t cmd_count = 0;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand) ++cmd_count;
  CHECK(cmd_count >= 32u);
}

TEST_CASE("drain() does NOT issue Abstract Commands for FPRs/CSRs/PMPs - those "
          "fields are zero in the bare drain output and merged in by "
          "drain_with_passthrough")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_fpr(i)] = 0xf000000000000000ULL + i;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain();

  for (int i = 0; i < 32; ++i) CHECK(state.fpr[i] == 0u);
  CHECK(state.mstatus == 0u);
  CHECK(state.satp    == 0u);
  CHECK(state.vlenb   == 0u);
}

TEST_CASE("drain_with_passthrough copies CSR/PMP/V-payload slots from input and "
          "freshly drains GPRs/PC from the DM")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80001234ULL;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_gpr(i)] = 0x10000000ULL + i;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;
  input.mstatus = 0x1800ULL;
  input.satp    = 0x8000000080000000ULL;
  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  input.pmpcfg[i]  = 0xa0 + i;
  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) input.pmpaddr[i] = 0xb0 + i;
  input.vlenb = 64;
  for (std::size_t i = 0; i < sizeof(input.vreg); ++i) input.vreg[i] = i & 0xff;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.mstatus == 0x1800ULL);
  CHECK(state.satp    == 0x8000000080000000ULL);
  CHECK(state.pmpcfg[5]  == uint64_t(0xa5));
  CHECK(state.pmpaddr[7] == uint64_t(0xb7));
  CHECK(state.vlenb == 64ULL);
  CHECK(state.vreg[100] == uint8_t(100));

  // GPRs/PC come from the DM read, not the input.
  for (int i = 1; i < 32; ++i)
    CHECK(state.gpr[i] == 0x10000000ULL + uint64_t(i));
  CHECK(state.pc == 0x80001234ULL);
}

TEST_CASE("drain_with_passthrough with HYBRID_FLAG_FP: FPRs read from DM, not input")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_fpr(i)] = 0xf000000000000000ULL + i;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.priv    = 3;
  // Stale QEMU1 values that must be overwritten by the DM reads.
  for (int i = 0; i < 32; ++i) input.fpr[i] = 0xdeadbeef00000000ULL + i;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  for (int i = 0; i < 32; ++i)
    CHECK(state.fpr[i] == 0xf000000000000000ULL + uint64_t(i));
}

TEST_CASE("drain_with_passthrough with HYBRID_FLAG_FP: FP reads issued after GPR reads")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.priv    = 3;

  hybrid::StateDrain drain(bus);
  (void) drain.drain_with_passthrough(input);

  std::optional<std::size_t> last_gpr_cmd;
  std::optional<std::size_t> first_fpr_cmd;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    const uint16_t regno = op.value & 0xFFFFu;
    if (regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
      last_gpr_cmd = i;
    if (!first_fpr_cmd
        && regno >= hybrid::regno_fpr(0) && regno <= hybrid::regno_fpr(31))
      first_fpr_cmd = i;
  }
  REQUIRE(last_gpr_cmd.has_value());
  REQUIRE(first_fpr_cmd.has_value());
  CHECK(*last_gpr_cmd < *first_fpr_cmd);
}

TEST_CASE("L20: drain_with_passthrough with HYBRID_FLAG_FP: fcsr read from "
          "DM, not input")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrFcsr)] = 0x45;  // frm=RDN | NX|UF

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.priv    = 3;
  input.fcsr    = 0x21;  // stale QEMU1 value; must be overwritten

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.fcsr == 0x45u);
}

TEST_CASE("L20: drain_with_passthrough without HYBRID_FLAG_FP: fcsr stays "
          "pass-through, no CSR 0x003 read")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrFcsr)] = 0x45;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;  // no HYBRID_FLAG_FP
  input.priv    = 3;
  input.fcsr    = 0x21;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.fcsr == 0x21u);
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    CHECK((op.value & 0xFFFFu) != hybrid::regno_csr(RD::kCsrFcsr));
  }
}

TEST_CASE("drain_with_passthrough without HYBRID_FLAG_FP: no FPR Abstract Commands issued")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;  // no HYBRID_FLAG_FP
  input.priv    = 3;
  for (int i = 0; i < 32; ++i) input.fpr[i] = 0xdeadbeef00000000ULL + i;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  // No FPR COMMAND reads issued.
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    const uint16_t regno = op.value & 0xFFFFu;
    const bool is_fpr = regno >= hybrid::regno_fpr(0)
                     && regno <= hybrid::regno_fpr(31);
    CHECK_FALSE(is_fpr);
  }

  // FPR slots remain pass-through from input (stale QEMU1 snapshot).
  for (int i = 0; i < 32; ++i)
    CHECK(state.fpr[i] == 0xdeadbeef00000000ULL + uint64_t(i));
}

TEST_CASE("L23: drain_with_passthrough re-reads mscratch from the hart, not "
          "the QEMU1 passthrough snapshot")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  // Post-ROI value left in the hart's mscratch by the measured region.
  bus.regfile[hybrid::regno_csr(RD::kCsrMscratch)] = 0xBADC0FFEE0DDF00DULL;

  hybrid_state_v1 input{};
  input.magic    = HYBRID_STATE_MAGIC;
  input.version  = HYBRID_STATE_VERSION;
  input.flags    = HYBRID_FLAG_RV64;
  input.priv     = 3;
  input.mscratch = 0xCAFEBABEDEADBEEFULL;  // stale QEMU1 value; must NOT survive

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.mscratch == 0xBADC0FFEE0DDF00DULL);
}

TEST_CASE("L24: drain_with_passthrough re-reads mepc/mcause/mtval/mip/mie from "
          "the hart, not the QEMU1 passthrough snapshot")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  // Post-ROI values the measured region left in the hart's M-mode CSRs.
  bus.regfile[hybrid::regno_csr(RD::kCsrMepc)]   = 0x111ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrMcause)] = 0x222ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrMtval)]  = 0x333ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrMip)]    = 0x444ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrMie)]    = 0x555ULL;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;
  // Stale QEMU1 values; none must survive into the drained state.
  input.mepc   = 0xDEAD0001ULL;
  input.mcause = 0xDEAD0002ULL;
  input.mtval  = 0xDEAD0003ULL;
  input.mip    = 0xDEAD0004ULL;
  input.mie    = 0xDEAD0005ULL;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.mepc   == 0x111ULL);
  CHECK(state.mcause == 0x222ULL);
  CHECK(state.mtval  == 0x333ULL);
  CHECK(state.mip    == 0x444ULL);
  CHECK(state.mie    == 0x555ULL);
}

TEST_CASE("L6: drain reads the hart privilege from dcsr.prv")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  // dcsr: xdebugver=4, cause=3 (haltreq), prv=1 (S-mode at halt).
  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x400000C1ULL;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain();

  CHECK(state.priv == 1u);
}

TEST_CASE("L6: drain_with_passthrough reports the freshly drained privilege, "
          "not the QEMU1 snapshot's")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x40000000ULL;  // prv=0 (U)

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;  // stale: QEMU1 drained M before the ROI dropped to U

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.priv == 0u);
}

// GPR/FPR/CSR drain is Abstract-Command-only: every register and CSR is read
// one abstract command each, directly into the drained state. The Program
// Buffer is reserved for state the abstract command space cannot reach, so
// the drain must issue NO PB execution.
TEST_CASE("drain reads GPRs and FPRs via abstract reads only -- no PB "
          "store-sweep")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize = 8
  for (uint16_t i = 1; i < 32; ++i)
    bus.regfile[hybrid::regno_gpr(i)] = 0xC0000000ULL + i;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_fpr(i)] = 0xD0000000ULL + i;
  bus.regfile[hybrid::regno_csr(RD::kCsrFcsr)] = 0x45;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.priv    = 3;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_with_passthrough(input);

  // Every GPR/FPR value arrives via its abstract read...
  for (int i = 1; i < 32; ++i)
    CHECK(state.gpr[i] == 0xC0000000ULL + uint64_t(i));
  for (int i = 0; i < 32; ++i)
    CHECK(state.fpr[i] == 0xD0000000ULL + uint64_t(i));
  CHECK(state.fcsr == 0x45u);

  // ...and no Program-Buffer execution occurred at all -- nothing in this
  // drain needs state the abstract command space cannot reach.
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}
